// Package queue keeps pending jobs in memory.
package queue

import (
	"errors"
	"sync"
)

// ErrEmpty means the queue holds no job.
var ErrEmpty = errors.New("queue: empty")

type Queue struct {
	mu   sync.Mutex
	jobs []string // pending job ids, oldest first
}

// Push appends a job id.
func (q *Queue) Push(id string) {
	q.mu.Lock()
	defer q.mu.Unlock()
	q.jobs = append(q.jobs, id)
}

// Pop removes the oldest job id.
func (q *Queue) Pop() (string, error) {
	q.mu.Lock()
	defer q.mu.Unlock()
	if len(q.jobs) == 0 {
		return "", ErrEmpty
	}
	id := q.jobs[0]
	q.jobs = q.jobs[1:]
	return id, nil
}
